                # Convert to numpy array for NA checking
                m_array = np.asarray(m)

                # Check for NAs
                is_NA = NA_action_obj.is_numerical_NA(m_array)

                # Handle NAs using the NAAction
                if np.any(is_NA):
                    # For direct matrix input, we treat the entire matrix as one "factor"
                    values = [m_array]
                    is_NAs = [is_NA]
                    origins = [None]
                    new_values = NA_action_obj.handle_NA(values, is_NAs, origins)
                    m_array = new_values[0]

                    # Update the original matrix format if needed
                    if have_pandas and isinstance(m, (pandas.Series, pandas.DataFrame)):
                        # Preserve pandas structure but with cleaned data
                        if isinstance(m, pandas.Series):
                            m = pandas.Series(m_array, index=m.index[~is_NA] if hasattr(m, 'index') else None)
                        elif isinstance(m, pandas.DataFrame):
                            m = pandas.DataFrame(m_array, 
                                               index=m.index[~is_NA] if hasattr(m, 'index') else None,
                                               columns=m.columns)
                    else:
                        m = m_array

                di = DesignInfo.from_array(m, default_column_prefix)
                if have_pandas and isinstance(m, (pandas.Series, pandas.DataFrame)):
                    orig_index = m.index
                else:
                    orig_index = None
                if return_type == "dataframe":
                    m = atleast_2d_column_default(m, preserve_pandas=True)
                    m = pandas.DataFrame(m)
                    m.columns = di.column_names
                    m.design_info = di
                    return (m, orig_index)
                else:
                    return (DesignMatrix(m, di), orig_index)

            rhs, rhs_orig_index = _regularize_matrix_with_na_handling(rhs, "x")
            if lhs is None:
                lhs = np.zeros((rhs.shape[0], 0), dtype=float)
            lhs, lhs_orig_index = _regularize_matrix_with_na_handling(lhs, "y")

            assert isinstance(getattr(lhs, "design_info", None), DesignInfo)
            assert isinstance(getattr(rhs, "design_info", None), DesignInfo)
            if lhs.shape[0] != rhs.shape[0]:
                raise PatsyError(
                    "shape mismatch: outcome matrix has %s rows, "
                    "predictor matrix has %s rows" % (lhs.shape[0], rhs.shape[0])
                )
            if rhs_orig_index is not None and lhs_orig_index is not None:
                if not rhs_orig_index.equals(lhs_orig_index):
                    raise PatsyError(
                        "index mismatch: outcome and predictor have incompatible indexes"
                    )
            return (lhs, rhs)

    # Apply the patch
    patsy.highlevel._do_highlevel_design = _do_highlevel_design

# Apply the patch when this module is imported
patch_do_highlevel_design()
